update public.learning_paths
set
  title = '2-D Design / Visual Foundations',
  goal = '2-D Design / Visual Foundations',
  summary = 'Point, line, plane, shape, value, texture, scale, color, and typography function as visual components, arranged through alignment, proximity, contrast, repetition, unity, variety, and emphasis. The course also covers visual weight and reading order, depth and spatial ambiguity, black-and-white abstraction, modular pattern, positive and negative space, pacing and sequence, color for hierarchy and brand tone, digital file production, design rationale, and a portfolio-ready visual system.',
